export const source = "Local date &orig_value_key;\nLocal string &adr_type_key;\nComponent boolean &rec_delete;\nComponent number &n_element;\nComponent array of array of string &a_FieldList;\nComponent boolean &chevron_click;\n/*bring for switch*/\nComponent date &eff_chg;\nComponent string &ad_chg;\n\nComponent date &CURR_ADDR_DT;\n\nIf &chevron_click = True Then\n   \n   &orig_value_key = ADDRESS_TYPE_FL.EFFDT.OriginalValue;\n   &adr_type_key = ADDRESS_TYPE_FL.ADDRESS_TYPE.Value;\n   &eff_chg = ADDRESS_TYPE_FL.EFFDT.Value;\n   &ad_chg = ADDRESS_TYPE_FL.ADDRESS_TYPE.Value;\n   \n   &rec = CreateRecord(Record.ADDRESS_DEL_WR);\n   &rec.EMPLID.Value = ADDRESS_TYPE_FL.EMPLID.Value;\n   &rec.ADDRESS_TYPE.Value = &adr_type_key;\n   &rec.EFFDT.Value = &orig_value_key;\n   &rec.Insert();\n   SQLExec(\"COMMIT\");\n   &chevron_click = False;\nElse\n   &eff_chg = ADDRESS_TYPE_FL.EFFDT.Value;\n   &ad_chg = ADDRESS_TYPE_FL.ADDRESS_TYPE.Value;\n   &chevron_click = False;\nEnd-If;\n&rec_delete = True;\n/*ADDRESSES.EFFDT.FC*/\n/* Sets the Current Effective aDDRESSES EFFDT in order to determine which values to load for DERIVED_PDE_CUR record at level 0 */\nIf CurrentRowNumber() = 1 Then\n   If ADDRESS_TYPE_FL.EFFDT <= %Date Then\n      &CURR_ADDR_DT = ADDRESS_TYPE_FL.EFFDT;\n   End-If;\nEnd-If;\n";
